from pathlib import Path
from filetype import guess
import subprocess
from uuid import uuid4
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ExecutionError(Exception):
    """
    An execution failed.
    """

    def __init__(self, stdout, stderr, exit_status, **kwargs):
        super(ExecutionError, self).__init__(**kwargs)
        self.stdout = stdout
        self.stderr = stderr
        self.exit_status = exit_status

    def __str__(self):
        return f"stdout={self.stdout!r}, stderr={self.stderr!r}, exit_status={self.exit_status!r}"

    def __repr__(self):
        return f"ExecutionError(stdout={self.stdout!r}, stderr={self.stderr!r}, exit_status={self.exit_status!r})"


class Executor:
    @staticmethod
    def execute(command, cwd=None):
        logger.debug(f"Executing {command!r} in {cwd!r}")
        popen = subprocess.Popen(
            command,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            cwd=cwd
        )
        stdout, stderr = popen.communicate()
        exit_status = popen.wait()
        logger.debug(f"stdout={stdout!r}, stderr={stderr!r}, exit_status={exit_status!r}")

        if exit_status != 0 or stderr:
            raise ExecutionError(stdout, stderr, exit_status)


def extract(
        path,
        output_dir=".",
        relative_to_cwd=False,
        **selections):
    """
     Recursively extract a selection of path patterns from an archive file into an output directory.

    The extraction ends, when no more archive files can be unpacked according to the selection criteria.


    :param str path: file to unpack.
    :param str output_dir: (optional) directory to extract files. Default ".".
            if existing, extracted files are merged with rsync.
    :param bool relative_to_cwd: (optional) if True, output directory will be created relative to current
            working directory, else relative to the path of the archive. default is False
    :param dict selections: (optional) specify what to extract.
                        Each key is a path of an archive, that shall be unpacked. The keys are used in glob() to
                        retrieve files for further unpack.
                        Each value is a pattern of files, that shall be extracted from the archive. The values are
                        used in 7z -i wildcard option.
                        default is {[.=*],[**/*=*]}'. Everything recursive extracted from file collection
    :return:

    .. code-block:: robotframework

        *** Settings ***
        Library    taf.file.pack

        *** Test Cases ***
        Extract pcap from snapshot

            Extract
            ...  path=/tmp/snapshot.zip
            ...  output_dir=snap
            ...  .=*
            ...  *=*coldreset*
            ...  **/*=*startup*
            ...  **=*pcap

        Extract 5gm from dcap.zip

            Extract
            ...  path=/tmp/dcap.zip
            ...  .=*/*/5g/controlPlane/*.5gm
    """

    local_executor = _create_local_executor()
    if not selections:
        selections = {".": "*", "**/*": "*"}
    logger.info(f"Unpacking name {path!r} output_dir {output_dir!r} selections {selections!r}")
    path = Path(path).resolve()
    directory = str(path.parent)
    filename = str(path.name)

    if relative_to_cwd:
        output_dir = (Path.cwd() / output_dir).resolve()

    local_executor.execute(
        f"ln '{filename}' '{filename}.bak'",
        cwd=directory)
    _extract_selections(path, selections, local_executor)

    # raise exception if filename is not a directory i.e. no files were extracted
    if not path.is_dir():
        local_executor.execute(f"unlink '{filename}.bak'", cwd=directory)
        raise RuntimeError(f"No files were extracted for the given selections: {selections!r}")

    local_executor.execute(
        f"mkdir -p '{output_dir}' ;"
        f"rsync -av '{filename}'/* '{output_dir}' ; "
        f"rm -rf '{filename}' ; "
        f"mv '{filename}.bak' '{filename}' ;",
        cwd=directory)


def _extract_selections(path, selections, local_executor):
    changed = True
    directory = path.parent
    filename = path.name
    guessed_files = set()
    while changed:
        changed = False
        for archive_rel_paths, pattern in selections.items():
            glob_pattern = _construct_glob_pattern(filename, archive_rel_paths)
            for archive_path in directory.glob(glob_pattern):
                if archive_path not in guessed_files:
                    changed |= _process_archive(archive_path, pattern, guessed_files, local_executor)


def _extract_archive(archive_path, pattern, local_executor):
    archive_path = Path(archive_path)
    archive_dir = str(archive_path.parent)
    archive_file = str(archive_path.name)
    extract_dir = str(uuid4())

    try:
        local_executor.execute(
            f"7z x -o{extract_dir} -i!'{pattern}' -aos '{archive_file}' -pxxx",
            cwd=archive_dir)
    except ExecutionError as e:
        if "ERROR: Wrong password" in e.stderr.decode():
            logger.info(f"Skipping password protected archive {archive_file!r}", )
            local_executor.execute(f"rm -rf '{extract_dir}'", cwd=archive_dir)
            return False
        logger.debug(f"Extraction failed for the file {archive_file!r} with error: {e.stderr!r}")

    if (archive_path.parent / extract_dir).is_dir():
        local_executor.execute(
            f"rm '{archive_file}' ; "
            f"mv '{extract_dir}' '{archive_file}'",
            cwd=archive_dir)
        return True
    return False


def _construct_glob_pattern(filename, archive_rel_paths):
    return f"{filename}/{archive_rel_paths}"


def _process_archive(archive_path, pattern, guessed_files, local_executor):
    extension = None
    if archive_path.is_file():
        file_type = guess(str(archive_path))
        guessed_files.add(archive_path)
        if file_type is not None:
            extension = file_type.extension

    if extension in ("7z", "gz", "tar", "xz", "zip"):
        return _extract_archive(archive_path, pattern, local_executor)

    return False


def _create_local_executor():
    return Executor()
